// Registers this toolkit's MCP servers with Pi's built-in MCP support.
// Generated by scripts/build.mjs from toolkit.json; edit the template in adapters/pi/.
//
// - Secrets are never stored here: headers reference ${ENV} variables that Pi
//   expands when connecting.
// - A server whose variable is unset is skipped, so missing credentials do not
//   produce failing connections.
// - A server with the same name in ~/.pi/agent/mcp.json or .pi/mcp.json takes
//   precedence over this registration, so existing user configuration wins.
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

type Server = { name: string; requiresEnv: string[]; config: Record<string, unknown> };

const SERVERS: Server[] = /*SERVERS*/ [];

export default function (pi: ExtensionAPI) {
  for (const server of SERVERS) {
    if (server.requiresEnv.some((name) => !process.env[name])) continue;
    try {
      pi.registerMcpServer(server.name, server.config as Parameters<ExtensionAPI["registerMcpServer"]>[1]);
    } catch {
      // Pi throws when another extension owns this name or the config is invalid; skip the server rather than fail loading.
    }
  }
}
